  KEY `idx_workflow_task_batch_id_workflow_node_id` (`workflow_task_batch_id`,`workflow_node_id`)
) ENGINE=InnoDB AUTO_INCREMENT=25452 DEFAULT CHARSET=utf8mb4 COMMENT='任务批次';
