n#break\r\n#end\r\n#end\r\n#foreach ($column in $columns)\r\n#if($column.htmlType == \"datetime\" && $column.queryType == \"BETWEEN\")\r\n#set($AttrName=$column.javaField.substring(0,1).toUpperCase() + ${column.javaField.substring(1)})\r\n  proxy?.addDateRange(queryParams.value, dateRange${AttrName}.value, \'${AttrName}\');\r\n#end\r\n#end\r\n  const res = await list${BusinessName}(queryParams.value);\r\n  const data = proxy?.handleTree(res.data, \"${treeCode}\", \"${treeParentCode}\");\r\n  if (data) {\r\n    ${businessName}List.value = data;\r\n    loading.value = false;\r\n  }\r\n}\r\n\r\n/** 查询${functionName}下拉树结构 */\r\nconst getTreeselect = async () => {\r\n  const res = await list${BusinessName}();\r\n  ${businessName}Options.value = [];\r\n  const data: ${BusinessName}Option = { ${treeCode}: 0, ${treeName}: \'顶级节点\', children: [] };\r\n  data.children = proxy?.handleTree(res.data, \"${treeCode}\", \"${treeParentCode}\");\r\n  ${businessName}Options.value.push(data);\r\n}\r\n\r\n// 取消按钮\r\nconst cancel = () => {\r\n  reset();\r\n  dialog.visible = false;\r\n}\r\n\r\n// 表单重置\r\nconst reset = () => {\r\n  form.value = {...initFormData}\r\n  ${businessName}FormRef.value?.resetFields();\r\n}\r\n\r\n/** 搜索按钮操作 */\r\nconst handleQuery = () => {\r\n  getList();\r\n}\r\n\r\n/** 重置按钮操作 */\r\nconst resetQuery = () => {\r\n#foreach ($column in $columns)\r\n#if($column.htmlType == \"datetime\" && $column.queryType == \"BETWEEN\")\r\n#set($AttrName=$column.javaField.substring(0,1).toUpperCase() + ${column.javaField.substring(1)})\r\n  dateRange${AttrName}.value = [\'\', \'\'];\r\n#end\r\n#end\r\n  queryFormRef.value?.resetFields();\r\n  handleQuery();\r\n}\r\n\r\n/** 新增按钮操作 */\r\nconst handleAdd = (row?: ${BusinessName}VO) => {\r\n  reset();\r\n  getTreeselect();\r\n  if (row != null && row.${treeCode}) {\r\n    form.value.${treeParentCode} = row.${treeCode};\r\n  } else {\r\n    form.value.${treeParentCode} = 0;\r\n  }\r\n  dialog.visible = true;\r\n  dialog.title = \"添加$