*\r\n   * $column.columnComment\r\n   */\r\n  $column.javaField:#if($column.javaField.indexOf(\"id\") != -1 || $column.javaField.indexOf(\"Id\") != -1) string | number;\r\n                        #elseif($column.javaType == \'Long\' || $column.javaType == \'Integer\' || $column.javaType == \'Double\' || $column.javaType == \'Float\' || $column.javaType == \'BigDecimal\') number;\r\n                        #elseif($column.javaType == \'Boolean\') boolean;\r\n                        #else string;\r\n                    #end\r\n#if($column.htmlType == \"imageUpload\")\r\n  /**\r\n   * ${column.columnComment}Url\r\n   */\r\n  ${column.javaField}Url: string;\r\n#end\r\n#end\r\n#end\r\n#if ($table.tree)\r\n    /**\r\n     * 子对象\r\n     */\r\n    children: ${BusinessName}VO[];\r\n#end\r\n}\r\n\r\nexport interface ${BusinessName}Form extends BaseEntity {\r\n#foreach ($column in $columns)\r\n#if($column.insert || $column.edit)\r\n  /**\r\n   * $column.columnComment\r\n   */\r\n  $column.javaField?:#if($column.javaField.indexOf(\"id\") != -1 || $column.javaField.indexOf(\"Id\") != -1) string | number;\r\n                        #elseif($column.javaType == \'Long\' || $column.javaType == \'Integer\' || $column.javaType == \'Double\' || $column.javaType == \'Float\' || $column.javaType == \'BigDecimal\') number;\r\n                        #elseif($column.javaType == \'Boolean\') boolean;\r\n                        #else string;\r\n                    #end\r\n#end\r\n#end\r\n}\r\n\r\nexport interface ${BusinessName}Query #if(!${treeCode})extends PageQuery #end{\r\n\r\n#foreach ($column in $columns)\r\n#if($column.query)\r\n  /**\r\n   * $column.columnComment\r\n   */\r\n  $column.javaField?:#if($column.javaField.indexOf(\"id\") != -1 || $column.javaField.indexOf(\"Id\") != -1) string | number;\r\n                        #elseif($column.javaType == \'Long\' || $column.javaType == \'Integer\' || $column.javaType == \'Double\' || $column.javaType == \'Float\' || $column.javaType == \'BigDecimal\') number;\r\n                        #elseif($column.javaType == \'Boolean\') boolean;\r\n                        #else string;\r\n                    #end\r\n#end\r\n#end\r\n    /**\r\n     * 日期范围参数\r\n     */\r\n    params?: any;\r\n}\r\n\r\n\r\n\r\n',1,7,'test'),(30,'vo.java','vo.java','vo.java','package ${packageName}.domain.vo;\r\n\r\n#foreach ($import in $importList)\r\nimport ${import};\r\n#end\r\nimport ${packageName}.domain.${ClassName};\r\nimport com.alibaba.excel.annotation.ExcelIgnoreUnannotated;\r\nimport com.alibaba.excel.annotation.ExcelProperty;\r\nimport com.formssi.common.excel.annotation.ExcelDictFormat;\r\nimport com.formssi.common.excel.convert.ExcelDictConvert;\r\nimport io.github.linpeilie.annotations.AutoMapper;\r\nimport lombok.Data;\r\n\r\nimport java.io.Serial;\r\nimport java.io.Serializable;\r\nimport java.util.Date;\r\n\r\n\r\n\r\n/**\r\n * ${functionName}视图对象 ${tableName}\r\n *\r\n * @author ${author}\r\n * @date ${datetime}\r\n */\r\n@Data\r\n@ExcelIgnoreUnannotated\r\n@AutoMapper(target = ${ClassName}.class)\r\npublic class ${ClassName}Vo implements Serializable {\r\n\r\n    @Serial\r\n    private static final long serialVersionUID = 1L;\r\n\r\n#foreach ($column in $columns)\r\n#if($column.list)\r\n    /**\r\n     * $column.columnComment\r\n     */\r\n#set($parentheseIndex=$column.columnComment.indexOf(\"（\"))\r\n#if($parentheseIndex != -1)\r\n#set($comment=$column.columnComment.substring(0, $parentheseIndex))\r\n#else\r\n#set($comment=$column.columnComment)\r\n#end\r\n#if(${column.dictType} && ${column.dictType} != \'\')\r\n    @ExcelProperty(value = \"${comment}\", converter = ExcelDictConvert.class)\r\n    @ExcelDictFormat(dictType = \"${column.dictType}\")\r\n#elseif($parentheseIndex != -1)\r\n    @ExcelProperty(value = \"${comment}\", converter = ExcelDictConvert.class)\r\n    @ExcelDictFormat(readConverterExp = \"$column.readConverterExp()\")\r\n#else\r\n    @ExcelProperty(value = \"${comment}\")\r\n#end\r\n    private $column.javaType $column.javaField;\r\n\r\n#if($column.htmlType == \"imageUpload\")\r\n    /**\r\n     * ${column.columnComment}Url\r\n     */\r\n    @Translation(type = TransConstant.OSS_ID_TO_URL, mapper = \"${column.javaField}\")\r\n    private String ${column.javaField}Url\";\r\n#end\r\n#end\r\n#end\r\n\r\n}\r\n',1,7,'test'),(31,'service','service','${context.javaBeanName}Service.java','## filename=${context.javaBeanName}Service.java, folder=service\n#set($entityClass=\"${context.classNamePascal}\")\n#set($mapperClass=\"${context.classNamePascal}Mapper\")\n#set($pkg=\"${context.packageName}\")\npackage ${pkg}.mapper;\n\nimport com.gitee.fastmybatis.core.support.BaseLambdaService;\nimport ${pkg}.dao.entity.${entityClass};\nimport ${pkg}.dao.mapper.${mapperClass};\nimport org.springframework.stereotype.Service;\n\n\n/**\n * @author ${context.author}\n */\n@Service\npublic class ${entityClass}Service extends BaseLambdaService {\n\n  // 131332123\n}',0,8,'lowCode'),(32,'mapper','mapper','${context.javaBeanName}Mapper.java','## filename=${context.javaBeanName}Mapper.java, folder=mapper\n#set($entityClass=\"${context.classNamePascal}\")\n#set($pkg=\"${context.packageName}\")\npackage ${pkg}.dao.mapper;\n\nimport com.gitee.fastmybatis.core.mapper.BaseMapper;\nimport ${pkg}.dao.entity.${entityClass};\n\n/**\n * @author ${context.author}\n */\npublic interface ${entityClass}Mapper extends BaseMapper {\n	\n}',0,8,'lowCode'),(33,'controller','controller','${context.javaBeanName}Controller.java','## filename=${context.javaBeanName}Controller.java, folder=controller\n#set($entityClass=\"${context.classNamePascal}\")\n#set($entityObj=\"${context.classNameCamel}\")\n#set($serviceClass=\"${context.classNamePascal}Service\")\n#set($serviceObj=\"${context.classNameCamel}Service\")\n#set($pkg=\"${context.packageName}\")\npackage ${pkg}.web.controller;\n\nimport com.gitee.fastmybatis.core.PageInfo;\nimport com.gitee.fastmybatis.core.query.Query;\nimport com.gitee.fastmybatis.